#!/usr/bin/env python3
import sys
import json
import time
import urllib.request
import urllib.error

API_URL = "http://127.0.0.1:4000/v1/chat/completions"
PROMPT = "Reply with exactly one word: OK"

def load_models(path):
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        # common patterns: {"models": [...]}
        if "models" in data and isinstance(data["models"], list):
            return data["models"]
        # else try values
    raise ValueError("JSON must be a list of model names or a dict with key 'models'")

def make_request(payload, timeout=30):
    req = urllib.request.Request(
        API_URL,
        data=json.dumps(payload).encode("utf-8"),
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        body = resp.read().decode("utf-8")
        return json.loads(body)

def call_model(model, include_temp=True):
    payload = {
        "model": model,
        "messages": [{"role": "user", "content": PROMPT}],
        "max_tokens": 20,
    }
    if include_temp:
        payload["temperature"] = 0

    start = time.time()
    try:
        data = make_request(payload, timeout=30)
        latency = time.time() - start
        text = ""
        try:
            text = data["choices"][0]["message"]["content"]
        except Exception:
            text = json.dumps(data)[:200]
        return True, latency, text, None
    except urllib.error.HTTPError as e:
        latency = time.time() - start
        body = e.read().decode("utf-8", errors="ignore")
        return False, latency, body or str(e), e
    except Exception as e:
        latency = time.time() - start
        return False, latency, str(e), e

def test_model(model):
    ok, latency, text, err = call_model(model, include_temp=True)
    if ok:
        return True, latency, text

    # If error indicates unsupported parameter, retry without temperature
    lowered = (text or "").lower()
    if "temperature" in lowered and ("unsupported" in lowered or "not allowed" in lowered or "unknown" in lowered):
        ok2, latency2, text2, _ = call_model(model, include_temp=False)
        return ok2, latency2, text2
    return False, latency, text

def format_table(rows):
    headers = ["Model", "Status", "Latency", "Response"]
    col_widths = [len(h) for h in headers]
    for r in rows:
        for i, cell in enumerate(r):
            col_widths[i] = max(col_widths[i], len(cell))
    line = " | ".join(h.ljust(col_widths[i]) for i, h in enumerate(headers))
    sep = "-+-".join("-" * col_widths[i] for i in range(len(headers)))
    out = [line, sep]
    for r in rows:
        out.append(" | ".join(r[i].ljust(col_widths[i]) for i in range(len(headers))))
    return "\n".join(out)

def main():
    if len(sys.argv) != 2:
        print("Usage: python test_models.py <models.json>")
        sys.exit(1)

    try:
        models = load_models(sys.argv[1])
    except Exception as e:
        print(f"Error loading models: {e}")
        sys.exit(1)

    results = []
    ok_count = 0
    fail_count = 0

    for model in models:
        ok, latency, text = test_model(model)
        status = "PASS" if ok else "FAIL"
        if ok:
            ok_count += 1
        else:
            fail_count += 1
        resp = (text or "").replace("\n", " ").strip()[:50]
        results.append([str(model), status, f"{latency:.2f}s", resp])

    print(format_table(results))
    print(f"Total: {len(models)} models | ✅ {ok_count} working | ❌ {fail_count} failed")

if __name__ == "__main__":
    main()
